/// <summary>
/// This class handles the main processing to perform the Update stock availlability details based on source of supply change.
/// </summary>
internal final class METUpdateStockAvailabilitySourceOfSupplyChangeService extends SysOperationServiceBase
{
    METStockAvailDate stockAvailabilityDate;
    EcoResProductLifecycleStateId productLifeCycleStateId;
    container newItemSitePair;
    int countOfRecords = 0 ;

}

Method.Source:
/// <summary>
/// This method begins or triggeres the process the Update stock availlability details based on source of supply change.
/// </summary>
/// <param name = "_contract">METUpdateStockAvailabilitySourceOfSupplyChangeContract class</param>
public void process(METUpdateStockAvailabilitySourceOfSupplyChangeContract _contract)
{
    if (METVendParameters::find().UpdateFromParentToTransferSites)
    {
        ReqItemTable reqItemTableAsPerContractParm;
        InventDim inventDim;            

        QueryRun queryRun = this.initialiseQueryRun(_contract);
        countOfRecords = SysQuery::countTotal(queryRun);

        if (countOfRecords)
        {
            while(queryRun.next())
            {
                try
                {
                    ReqItemTable reqItemTableSubSelection;
                    InventDim    iventDimSubSelection;

                    reqItemTableAsPerContractParm = queryRun.get(tableNum(ReqItemTable));
                    inventDim                     = queryRun.get(tableNum(InventDim));

                    if (METInventItemOrderSetup::findByItemAndSite(reqItemTableAsPerContractParm.ItemId, inventDim.InventSiteId).ItemStatus == '')
                    {
                        warning(strFmt("@MET:JobExitedDueToBlankStatus", inventDim.InventSiteId, reqItemTableAsPerContractParm.ItemId));
                        return;
                    }

                    if (reqItemTableAsPerContractParm.ReqPOType == ReqPOType::Transfer)
                    {
                        while select reqItemTableSubSelection
                            where reqItemTableSubSelection.ItemId == reqItemTableAsPerContractParm.ItemId
                        join iventDimSubSelection
                            where iventDimSubSelection.inventDimId == reqItemTableSubSelection.CovInventDimId
                                && iventDimSubSelection.InventLocationId == reqItemTableAsPerContractParm.InventLocationIdReqMain //Coverage Warehouse == Main Warehouse
                        {
                            // Default order settings of Item and Site (here Coverage Site value is same as that of the Main warehouse, thus 'reqItemTableSubSelection' acting as Parent)
                            METInventItemOrderSetup metInventItemDOS = METInventItemOrderSetup::findByItemAndSite(reqItemTableSubSelection.ItemID, iventDimSubSelection.InventSiteId);

                            newItemSitePair = conIns(newItemSitePair,
                                                    conLen(newItemSitePair) + 1,
                                                    this.updateDefaultOrderSettingsForItemSite(reqItemTableAsPerContractParm.ItemID, inventDim.InventSiteId, metInventItemDOS));
                        }

                        //Loop through the newItemSitePair
                        this.processWithUpdateStockAvailabilityService(newItemSitePair);
                    }
                    else if (reqItemTableAsPerContractParm.ReqPOType == ReqPOType::Purch)
                    {
                        if (!reqItemTableAsPerContractParm.METInterCompanySourced || !reqItemTableAsPerContractParm.METIntercompanySourcedWarehouse)
                        {
                            Info(strFmt("@MET:ItemCoverageEitherNotEnabledAsIntercompanSourceOrIntercompanySourceWarehouseNoSet",
                            reqItemTableAsPerContractParm.ItemId,
                            inventDim.InventSiteId,
                            inventDim.InventLocationId,
                            enum2Str(reqItemTableAsPerContractParm.ReqPOType)
                            ));

                            continue;
                        }

                        DataAreaId metInterCompanyPurchaseLegalEntity = InventParameters::find().METInterCompanyPurchaseLegalEntity;
                        if (metInterCompanyPurchaseLegalEntity)
                        {
                            METInventItemOrderSetup metInventItemDOS;
                            changecompany(metInterCompanyPurchaseLegalEntity)
                            {
                                while select reqItemTableSubSelection
                                    where reqItemTableSubSelection.ItemId == reqItemTableAsPerContractParm.ItemId
                                join iventDimSubSelection
                                    where iventDimSubSelection.inventDimId == reqItemTableSubSelection.CovInventDimId
                                        && iventDimSubSelection.InventLocationId == reqItemTableAsPerContractParm.METIntercompanySourcedWarehouse
                                {
                                    metInventItemDOS = METInventItemOrderSetup::findByItemAndSite(reqItemTableSubSelection.ItemID, iventDimSubSelection.InventSiteId);
                                }
                            }

                            newItemSitePair = conIns(newItemSitePair,
                                                    conLen(newItemSitePair) + 1,
                                                    this.updateDefaultOrderSettingsForItemSite(reqItemTableAsPerContractParm.ItemID, inventDim.InventSiteId, metInventItemDOS));

                            //Loop through the newItemSitePair
                            if (newItemSitePair != conNull())
                            {
                                this.processWithUpdateStockAvailabilityService(newItemSitePair);
                            }
                            else
                            {
                                Info(strFmt("@MET:METStockAvail"));
                            }
                        }
                        else
                        {
                            Info(strFmt("@MET:CannotProceedUpdateStockAvailbilityBasedOnSourceOfSupplyChange ", curExt()));
                        }
                    }
                }
                catch(Exception::Error)
                {
                    str message = strFmt("@MET:UnexpectedErrorExecutingUpdateStocAvailabilityBasedOnSourceChange", _contract.parmInventLocationId(), _contract.parmPlannedOrderTpye());
                    error(this.catchMessages(_contract, message));
                }
            }
        }
        else
        {
            str message = strFmt("@MET:NoRecordsToProcessAnUpdateStockAvailabilityForProvidedParameters", _contract.parmInventLocationId(), _contract.parmPlannedOrderTpye());

            Info(this.catchMessages(_contract, message));
        }
    }
    else
    {
        Info("@MET:MetcashAPParameterForUpdateDatesStatesParentToTransferSitesNotEnabled");
    }
}

/// <summary>
/// Prepare query to process process item coverage records to Update stock availlability details based on source of supply change.
/// </summary>
/// <param name = "_contract">METUpdateStockAvailabilitySourceOfSupplyChangeContract class object</param>
/// <returns>QueryRun object genreated for the Item coverage records</returns>
private QueryRun initialiseQueryRun(METUpdateStockAvailabilitySourceOfSupplyChangeContract _contract)
{
    QueryRun queryRun;
    Query query = new Query(queryStr(METReqItemTableQuery));
    QueryBuildDataSource reqItemTableQBDS = query.dataSourceTable(tableNum(ReqItemTable));
    QueryBuildDataSource inventDimQBDS    = query.dataSourceTable(tableNum(InventDim));

    InventLocationId covInventLocationId             = _contract.parmInventLocationId();
    InventLocationId metInterCompanyInventLocationId = _contract.parmMetIntercompanySourcedWarehouseId();
    ItemId itemId                                    = _contract.parmItemId();
    NoYes metIntercompanySourced                     = _contract.parmMetIntercompanySourced();
    ReqPOType plannedOrderType                       = _contract.parmPlannedOrderTpye();

    if (itemId)
    {
        reqItemTableQBDS.addRange(fieldNum(ReqItemTable, ItemId)).value(queryValue(itemId));
    }

    if (covInventLocationId)
    {
        inventDimQBDS.addRange(fieldNum(InventDim, InventLocationId)).value(queryValue(covInventLocationId));
    }

    reqItemTableQBDS.addRange(fieldNum(ReqItemTable, ReqPOType)).value(enum2Str(plannedOrderType));

    if (plannedOrderType == ReqPOType::Purch)
    {
        if (metInterCompanyInventLocationId)
        {
            reqItemTableQBDS.addRange(fieldNum(ReqItemTable, METIntercompanySourcedWarehouse)).value(queryValue(metInterCompanyInventLocationId));
        }

        if (metIntercompanySourced)
        {
            reqItemTableQBDS.addRange(fieldNum(ReqItemTable, METInterCompanySourced)).value(queryValue(metIntercompanySourced));
        }
    }

    queryRun = new QueryRun(query);

    return queryRun;
}

/// <summary>
/// This method peforms the update of unique combinations of Default order settings.
/// </summary>
/// <param name = "_itemId">Unique ItemId</param>
/// <param name = "_inventSideId">Unique SiteId</param>
/// <param name = "_metInventItemDOS">METInventItemOrderSetup table buffer, parent Site details </param>
/// <returns>A container with Item, Site and Stock availability information</returns>
public container updateDefaultOrderSettingsForItemSite(ItemId _itemId, InventSiteId _inventSideId, METInventItemOrderSetup _metInventItemDOS)
{
    #OCCRetryCount

    if (_itemId && _inventSideId && _metInventItemDOS)
    {
        try
        {
            METInventItemOrderSetup metInventItemDOSUpdate = METInventItemOrderSetup::findByItemAndSite(_itemId, _inventSideId, true);

            if (metInventItemDOSUpdate.RecId
                && (metInventItemDOSUpdate.ItemStatus == enum2Str(METItemsStatus::Active) ||
                    metInventItemDOSUpdate.ItemStatus == enum2Str(METItemsStatus::Discontinued) ||
                    metInventItemDOSUpdate.ItemStatus == enum2Str(METItemsStatus::PackChange))
                )
            {
                ttsbegin;
                metInventItemDOSUpdate.StockAvailDate          = _metInventItemDOS.StockAvailDate;
                metInventItemDOSUpdate.ProductLifecycleStateId = _metInventItemDOS.ProductLifecycleStateId;
                metInventItemDOSUpdate.doUpdate();
                ttscommit;

                return [_itemId, _inventSideId, _metInventItemDOS.StockAvailDate, _metInventItemDOS.ProductLifecycleStateId];
            }
            else if(metInventItemDOSUpdate.RecId)
            {
                Info(strFmt("@MET:DefaultOrderSettingsCouldNotBeUpdatedDueToCurrentItemStatus", _itemId, _inventSideId));
            }                

            return conNull();
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch(Exception::Error)
        {
            throw  error(strFmt("@MET:UnexpectedErrorWhileUpdateStockAvailabilityDetails", _itemId, _inventSideId));
        }
    }

    return conNull();
}

/// <summary>
/// Method to peform the replnishment site updates.
/// </summary>
/// <param name = "_newItemSitePair">A container with unique combinations of Item and Site</param>
private void processWithUpdateStockAvailabilityService(container _newItemSitePair)
{
    for (int i = 1; i <= conLen(_newItemSitePair); i++)
    {
        container newEntry                                 = conPeek(_newItemSitePair, i);
        ItemId newItemId                                   = conPeek(newEntry, 1);
        InventSiteId newSiteId                             = conPeek(newEntry, 2);
        METStockAvailDate stockAvailDate                   = conPeek(newEntry, 3);
        EcoResProductLifecycleStateId prdtLifeCycleStateId = conPeek(newEntry, 4);

        METUpdateStockAvailabilityContract metUpdateStockAvailabilityContract = new METUpdateStockAvailabilityContract();
        metUpdateStockAvailabilityContract.parmItemId(newItemId);
        metUpdateStockAvailabilityContract.parmInventSiteId(newSiteId);
        metUpdateStockAvailabilityContract.parmMETStockAvailDate(stockAvailDate);
        metUpdateStockAvailabilityContract.parmProductLifecycleStateId(prdtLifeCycleStateId);

        METUpdateStockAvailabilityService  metUpdateStockAvailabilityService = new METUpdateStockAvailabilityService();
        metUpdateStockAvailabilityService.process(metUpdateStockAvailabilityContract);
    }
}

/// <summary>
/// Method to handle the messages during the process of updating stock availability details
/// </summary>
/// <param name = "_contract">METUpdateStockAvailabilitySourceOfSupplyChangeContract class object</param>
/// <param name = "_message">String message</param>
/// <returns>Updated or newly appended string message</returns>
private str catchMessages(METUpdateStockAvailabilitySourceOfSupplyChangeContract _contract, str _message = '')
{
    if (_contract && _message != '')
    {
        if ( _contract.parmItemId())
        {
            _message += strFmt("@MET:CatchMeassgeForItemParm",  _contract.parmItemId());
        }

        if ( _contract.parmMetIntercompanySourced())
        {
            _message += strFmt("@MET:CatchMeassgeForICSourceParm", enum2Str(_contract.parmMetIntercompanySourced()));
        }

        if (_contract.parmMetIntercompanySourcedWarehouseId())
        {
            _message += strFmt("@MET:CatchMessageIntercompanyWarhouse",  _contract.parmMetIntercompanySourcedWarehouseId());
        }
    }
    return _message;
}
